static void Print(in Point p) => Console.WriteLine(p.X);

var p = new Point(1, 2);
Print(in p);              // ссылка на p
Print(p);                 // то же, модификатор необязателен
Print(new Point(3, 4));   // ссылка на скрытую временную копию

