static ref readonly int Larger(ref readonly int a, ref readonly int b)
{
    if (a >= b) return ref a;
    return ref b;
}

int[] arr = [1, 7];
ref readonly int big = ref Larger(ref arr[0], in arr[1]);  // смотрит на arr[1]
Larger(in arr[0], 5);   // предупреждение: 5 — не переменная

